  "import.eyebrow": "Маълумот",
  "import.title": "Маркази воридот",
  "import.subtitleStart": "Се амалиёти ҷудогонаи ҷадвал, бинобар ин ислоҳи нарх ҳеҷ гоҳ наметавонад ҳамчун қабули захира биёяд. Ҳама чиз танҳо ба",
