  "import.createBusinessFirstShort": "Аввал тиҷорат эҷод кунед.",
  "import.whatEachDoes": "Ҳар амалиёт чӣ мекунад",
  "import.createTitle": "Эҷоди маҳсулоти нав",
  "import.createDesc": "сатрҳоеро илова мекунад, ки ҳанӯз дар каталог нестанд. SKU-ҳо ва штрих-кодҳои такрории аллакай истифодашуда гузаронида мешаванд ва захираи ибтидоӣ метавонад дар маконе, ки шумо ҳамчун қабул интихоб мекунед, ҷойгир шавад.",
  "import.updateTitle": "Навсозии маҳсулоти мавҷуда",
  "import.updateDesc": "ҳар сатрро аз рӯи SKU ё ID-и сабт мувофиқат мекунад ва арзиши кӯҳнаро дар паҳлӯи арзиши нави пешниҳодшуда нишон медиҳад. Ҳуҷайраҳои холӣ арзиши сабтшударо танҳо мегузоранд, агар шумо дархост накунед, ки ҷойҳои холӣ тоза карда шаванд ва миқдорҳо ҳеҷ гоҳ дахл карда намешаванд.",
  "import.receiveModeTitle": "Қабули захира",
  "import.receiveModeDesc": "миқдорҳои омадаро ба як макон илова мекунад ва барои ҳар сатр қабулро ба дафтари ҳаракат менависад. Ҳар партия қайд карда мешавад, бинобар ин ҳамон варақро ду маротиба қабул кардан мумкин нест.",
  "import.excelNote": "Китобҳои кории Excel (.xlsx) мустақиман хонда мешаванд — варақро интихоб кунед ва сутунҳо барои шумо мувофиқат карда мешаванд. Рамзҳо пурра мемонанд: UPC, ки ҳамчун матн сабт шудааст, рақамҳо ва сифрҳои пеши худро нигоҳ медорад. Сатрҳое, ки ворид карда намешаванд, бо сабаб номбар карда мешаванд",
  "import.excelNoteDownload": " ва метавонанд ҳамчун файл боргирӣ карда шаванд.",
