  "print.templateIsBusiness": "{label} хусусияти Business аст",
  "print.supplierBlockedDesc": "Ҳуҷҷатҳои таъминкунанда бо нақшаи Business мераванд — таъминкунандагон, харид ва фармоишҳои харид. Ҳама чизи ҳозираи шумо кор карданро идома медиҳад.",
  "print.seeBusiness": "Дидани он чи Business дар бар мегирад",
  "print.nothingToPrint": "Ҳанӯз чизе барои чоп нест",
  "print.pickOrderHint": "Фармоиши харидро аз рӯйхат интихоб кунед, то ҳуҷҷатро пешнамоиш кунед.",
  "print.pickCustomerOrderHint": "Фармоиши муштариро аз рӯйхат интихоб кунед, то ҳуҷҷатро пешнамоиш кунед.",
  "print.pickReturnHint": "Бозгашти сабтшударо аз рӯйхат интихоб кунед, то ҳуҷҷатро пешнамоиш кунед.",
  "print.chooseStyleHint": "Услубро интихоб кунед, сипас маҳсулотро аз рӯйхат интихоб кунед. Пешнамоиш маҳз он чиро нишон медиҳад, ки аз принтер берун меояд.",
  "print.howToReach": "Чӣ тавр ба принтери худ расидан",
  "print.howIntro": "Ин барнома ба принтерҳое пайваст мешавад, ки шумо аллакай доред — он худаш принтер нест. Чор роҳи расидан ба якто вуҷуд дорад ва барчаспҳо дар ҳарду нақша тавассути ҳама гунаи онҳо чоп мешаванд. Варақҳои бастабандӣ, фармоишҳои харид, ҳуҷҷатҳои таъминкунанда ва ҳисоботҳо танҳо Business мебошанд, новобаста аз пайвастшавӣ.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Аз ин саҳифа, дар Chrome ё Edge-и мизи корӣ ва дар Chrome-и Android: принтери барчаспи худро интихоб кунед ва барчаспҳо мустақиман ба он мераванд. Он дар Safari-и iOS кор намекунад — дар iPhone, чопи Bluetooth бо барномаи мобилӣ меояд. Принтере, ки танҳо бо Zebra ZPL ё забони худи Brother сухан мегӯяд, барчаспҳоеро, ки ин саҳифа мефиристад, намефаҳмад; ин дар муқобили принтерҳои воқеӣ санҷида мешавад, пеш аз он ки коркард номида шавад.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Принтерро дар Wi-Fi-и мағозаи худ насб кунед, сипас тугмаи Чопро истифода баред — он тавассути принтери дар ин компютер насбшуда, тавассути шабакаи мағоза чоп мекунад. Дар iPhone, AirPrint дарунсохта аст: принтери AirPrint дар ҳамон Wi-Fi танҳо дар варақаи чоп пайдо мешавад, сим ё барнома лозим нест ва барнома ба рамзи махсуси AirPrint ниёз надорад. Принтер бояд AirPrint-ро дастгирӣ кунад (аксари навҳо мекунанд) ва телефон ва принтер бояд дар ҳамон Wi-Fi бошанд.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Принтерро бо сими Ethernet ба шабакаи мағозаи худ пайваст кунед, онро дар компютер насб кунед ва тавассути тугмаи Чоп чоп кунед. Ethernet роҳи мизи корӣ ва компютер аст — iPhone-ҳо симҳои Ethernet-ро истифода намебаранд.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Принтерро бо сими он ба компютер пайваст кунед ва тугмаи Чопро истифода баред — он тавассути принтери дар он ҷо насбшуда чоп мекунад. Дар телефони Android бо сими USB OTG, тугмаи USB дар боло мустақиман бо принтер сухан мегӯяд. iPhone-ҳо наметавонанд мустақиман тавассути USB чоп кунанд — дар он ҷо WebUSB нест — бинобар ин Wi-Fi / AirPrint-ро истифода баред ё Bluetooth-ро аз барномаи мобилӣ истифода баред.",
  "print.howCordsLead": "Симҳо ҳанӯз ба iPhone-ҳо хизмат мерасонанд, як қадам дур.",
  "print.howCordsBody": "Принтери USB, ки ба компютери мағоза пайваст шудааст ё принтери Ethernet, ки ба шабака пайваст шудааст, дар iPhone-и шумо тавассути Wi-Fi-и мағоза пайдо мешавад (AirPrint / принтери мубодилашуда) — симҳо принтерро ба шабака устувор мегузоранд ва телефон ба он бесим мерасад.",
  "print.howOfflineLead": "Агар интернет қатъ шавад,",
  "print.howOfflineBody": "барчаспҳо ва ҳуҷҷатҳои аллакай дар ин саҳифа ҳанӯз чоп мешаванд — тугмаи Чоп, PDF-и барчаспҳо, Bluetooth ва USB ба пайвастшавӣ ниёз надоранд. Он чи ба интернет ниёз дорад, бор кардани саҳифа ва маҳсулоти он дар ҷои аввал аст. Ҳолати пурраи офлайн (кор дар барнома бе ҳеҷ пайвастшавӣ) сохти алоҳида ва калонтар аст ва дар ин ҷо даъво карда намешавад.",
