  "settings.cancelSubscription": "Бекор кардани обуна",
  "settings.cancelTerms.appleLink": "Дастурҳои бекоркунии Apple",
  "settings.cancelTerms.googlePlayLink": "Дастурҳои бекоркунии Google Play",
  "settings.cancelTerms.graceTitle": "Пас аз анҷоми давраи пардохтшудаи шумо — имтиёзи 15-рӯза, сипас несткунӣ:",
  "settings.cancelTerms.intro": "Ин шартҳо барои обунаҳои пардохтшудаи Luminous StockHaven мебошанд. Ҳисобдории обунаи вебсайт тавассути Stripe аст. Шумо метавонед обунаи худро дар ҳар вақт бо истифода аз тугмаи Бекор кардани обуна дар поён худатон бекор кунед — тасдиқи кормандон лозим нест. Дархостҳои бекоркунӣ ва баргардониданро инчунин тавассути тамоси расмии дастгирии муштарӣ, theluminousbookshop@outlook.com, идора кардан мумкин аст.",
  "settings.cancelTerms.noApprovalBody": "Шумо метавонед обунаи худро дар ҳар вақт худатон бекор кунед. Тасдиқи кормандон талаб карда намешавад. Навсозиҳои оянда танҳо пас аз тасдиқи провайдери ҳисобдорӣ бекоркуниро қатъ мекунанд.",
  "settings.cancelTerms.noApprovalTitle": "Бекор кардан бе тасдиқ:",
  "settings.cancelTerms.paymentBody": "Барои озмоишҳои пардохтшуда, озмоиши ҳафтрӯза ҳангоми сабти ном усули пардохтро талаб мекунад. Агар дар давоми мӯҳлати татбиқшавандаи бекоркунии озмоиш бекор карда нашавад, нақшаи моҳонаи интихобшуда пас аз озмоиш ба таври худкор ситонида мешавад. Нарх, санаи аввалини ҳисобдорӣ ва мӯҳлати бекоркунии махсуси провайдер бояд ҳангоми сабти ном нишон дода шаванд. Ҳисобдории озмоиш тавассути Stripe аст.",
  "settings.cancelTerms.paymentTitle": "Усули пардохт ва навсозии худкор:",
  "settings.cancelTerms.remainingBody": "Агар шумо аллакай барои давраи ҳисобдорӣ пардохт карда бошед, шумо метавонед дастрасиро то он санаи тасдиқшудаи пардохтшуда нигоҳ доред. Қатъи барвақт тасдиқи мувофиқи провайдер ва ҳама гуна коркарди баргардонидани татбиқшавандаро талаб мекунад. Дастрасии озмоиши ройгон мувофиқи санаи қатъи озмоиши аз ҷониби провайдер тасдиқшуда ба анҷом мерасад.",
  "settings.cancelTerms.remainingTitle": "Дастрасии боқимонда:",
  "settings.cancelTerms.storesBody": "Агар шумо ҳеҷ гоҳ тавассути Google Play ё Apple App Store обуна шавед, обунаи шумо аз ҷониби он мағоза ҳисобдорӣ ва идора карда мешавад. Шояд ба шумо лозим шавад, ки онро мустақиман дар қисмати обунаҳои ҳамон ҳисоби Google ё Apple, ки барои обуна истифода шудааст, бекор кунед. Бекор кардани обунаи алоҳидаи вебсайт, нест кардани ин барнома ё дархости нест кардани ҳисоби Luminous StockHaven обунаи аз ҷониби мағоза ҳисобдорӣшударо ба таври худкор бекор намекунад. Қабули хариди худро санҷед, то тасдиқ кунед, ки кӣ шуморо ҳисобдорӣ мекунад.",
  "settings.cancelTerms.storesTitle": "Обунаҳои Google Play ва Apple App Store (агар шумо ҳеҷ гоҳ тавассути мағоза обуна шавед):",
  "settings.cancelTerms.title": "Шартҳо ва Қоидаҳои Бекоркунӣ",
  "settings.cancelTerms.trialBody": "Озмоиши ҳафтрӯза танҳо як маротиба барои ҳар муштарии ҳақдор истифода шуда метавонад. Бекор кардани озмоиш ё обуна озмоиши дигарро намедиҳад; муштариёни бозгашта бояд обунаи пардохтшударо интихоб кунанд.",
  "settings.cancelTerms.trialTitle": "Як озмоиши ройгон:",
  "settings.canceled.endsOn": "Ин обуна бекор карда шудааст ва {date} ба анҷом мерасад. Шумо то он вақт дастрасии пурраро нигоҳ медоред.",
  "settings.delete.checking": "Дархости мавҷудаи несткунӣ санҷида шуда истодааст…",
  "settings.delete.description": "Дархости тоза кардани ҳисоби воридшавии Luminous StockHaven-и шумо.",
  "settings.delete.dialogDescription": "Ин баррасии нест кардани ҳисобро дархост мекунад. Он воридшавӣ ё инвентари шуморо фавран тоза намекунад ва он ҳеҷ обунаи Stripe-ро бекор намекунад. {word}-ро нависед, то тасдиқ кунед, ки шумо мехоҳед дархостро пешниҳод кунед.",
  "settings.delete.dialogTitle": "Дархости Нест кардани Ҳисоб",
  "settings.delete.enterDelete": "Барои тасдиқ {word}-ро ворид кунед",
  "settings.delete.exportFirst": "Агар ба шумо лозим бошад, ки сабтҳои худро нигоҳ доред, аввал инвентари худро содир кунед.",
  "settings.delete.intro": "Пешниҳоди дархост ҳисоб, тиҷоратҳо ё инвентари шуморо фавран нест намекунад. Дархостҳо пеш аз анҷом додани несткунӣ алоҳида баррасӣ карда мешаванд. Ин дархост обунаи Stripe-ро бекор намекунад ё ҳисобдории ояндаро қатъ намекунад; бекоркунии обуна бояд алоҳида тавассути провайдери ҳисобдорӣ идора карда шавад.",
  "settings.delete.keepAccount": "Нигоҳ доштани Ҳисоб",
  "settings.delete.noExport": "Essentials содирот надорад — пеш аз дархости несткунӣ ҳар чиро, ки ба шумо лозим аст, нависед.",
  "settings.delete.notDeleted": "Ҳисоб ва маълумоти шумо бо ин дархост нест карда нашудаанд. Ҳисобдорӣ бекор карда нашудааст.",
  "settings.delete.received": "Дархости нест кардани ҳисоби шумо гирифта шуд.",
